(function(){
const topic3CompleteLectureHTML="<h2 class=\"t3v2-title\"><div class=\"t3v2-lang t3v2-en\">Topic 3: The Art of the Picture Book</div><div class=\"t3v2-lang t3v2-zh\">主题三：图画书的艺术</div><div class=\"t3v2-lang t3v2-py\">Zhǔtí sān: Túhuàshū de yìshù</div></h2>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Learning Outcomes</div><div class=\"t3v2-lang t3v2-zh\">学习成果</div><div class=\"t3v2-lang t3v2-py\">Xuéxí Chéngguǒ</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">By the end of this topic, students should be able to:</div><div class=\"t3v2-lang t3v2-zh\">课程结束后，学生应该能够：</div><div class=\"t3v2-lang t3v2-py\">Kèchéng Jiéshù Hòu, Xuéshēng Yīnggāi Nénggòu:</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Identify the parts of a picture book.</div><div class=\"t3v2-lang t3v2-zh\">辨认图画书的各个部分。</div><div class=\"t3v2-lang t3v2-py\">Biànrèn Túhuàshū de Gègè Bùfen.</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Explain the purpose of paratext and peritext.</div><div class=\"t3v2-lang t3v2-zh\">解释副文本和周边文本的作用。</div><div class=\"t3v2-lang t3v2-py\">Jiěshì Fùwénběn Hé Zhōubiān Wénběn de Zuòyòng.</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Describe the importance of the double-page spread.</div><div class=\"t3v2-lang t3v2-zh\">说明跨页设计的重要性。</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng Kuàyè Shèjì de Zhòngyàoxìng.</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Explain how book design supports storytelling.</div><div class=\"t3v2-lang t3v2-zh\">解释书籍设计如何帮助讲故事。</div><div class=\"t3v2-lang t3v2-py\">Jiěshì Shūjí Shèjì Rúhé Bāngzhù Jiǎng Gùshì.</div></div>\n<h3 class=\"t3v2-section\"><div class=\"t3v2-lang t3v2-en\">3.1 Anatomy of a Picture Book</div><div class=\"t3v2-lang t3v2-zh\">图画书的结构</div><div class=\"t3v2-lang t3v2-py\">Túhuàshū de Jiégòu</div></h3>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">What Is a Picture Book?</div><div class=\"t3v2-lang t3v2-zh\">什么是绘本？</div><div class=\"t3v2-lang t3v2-py\">Shénme shì huìběn?</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">A picture book tells a story with words and pictures.</div><div class=\"t3v2-lang t3v2-zh\">图画书通过文字和图片讲故事。</div><div class=\"t3v2-lang t3v2-py\">Túhuàshū Tōngguò Wénzì Hé Túpiàn Jiǎng Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Pictures are as important as the words.</div><div class=\"t3v2-lang t3v2-zh\">图片和文字同样重要。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Hé Wénzì Tóngyàng Zhòngyào.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The pictures help children understand the story.</div><div class=\"t3v2-lang t3v2-zh\">图片帮助儿童理解故事。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Bāngzhù Értóng Lǐjiě Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">A picture book is made for young readers.</div><div class=\"t3v2-lang t3v2-zh\">图画书是为幼儿读者创作的。</div><div class=\"t3v2-lang t3v2-py\">Túhuàshū Shì Wèi Yòu'ér Dúzhě Chuàngzuò de.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Parts of a Picture Book</div><div class=\"t3v2-lang t3v2-zh\">图画书的构成部分</div><div class=\"t3v2-lang t3v2-py\">Túhuàshū de Gòuchéng Bùfen</div></h4><figure class=\"t3v3-collage\"><img alt=\"Visual overview of picture-book anatomy, illustration styles, lines, colours and composition; see corrected captions in the lecture.\" loading=\"lazy\" src=\"./assets/topic3_educational_collage_REVIEW.png\"/><figcaption>Visual teaching reference — illustration labels to be verified before public publication.</figcaption></figure>\n<section class=\"t3v5-terms\" aria-label=\"Correct terminology reference\"><h4>Correct Terminology Reference<br>正确术语参考<br>Zhèngquè shùyǔ cānkǎo</h4><p class=\"t3v5-caution\">For this private review, use the corrected terms below rather than the text printed inside the illustration.<br>本私人审阅版本请以以下正确术语为准，不要以插图内的文字为准。<br>Běn sīrén shěnyuè bǎnběn qǐng yǐ yǐxià zhèngquè shùyǔ wéi zhǔn, búyào yǐ chātú nèi de wénzì wéi zhǔn.</p><div class=\"t3v6-table-scroll\"><table class=\"t3v6-table\"><thead><tr><th scope=\"col\">English</th><th scope=\"col\">中文</th><th scope=\"col\">Pinyin</th></tr></thead><tbody><tr class=\"t3v6-category\"><th colspan=\"3\" scope=\"colgroup\">Parts of a Picture Book / 图画书的组成部分 / Túhuàshū de zǔchéng bùfen</th></tr><tr><td>Front cover</td><td lang=\"zh-Hans\">封面</td><td>Fēngmiàn</td></tr><tr><td>Back cover</td><td lang=\"zh-Hans\">封底</td><td>Fēngdǐ</td></tr><tr><td>Title page</td><td lang=\"zh-Hans\">书名页</td><td>Shūmíng yè</td></tr><tr><td>Endpapers</td><td lang=\"zh-Hans\">环衬</td><td>Huánchèn</td></tr><tr><td>Double-page spread</td><td lang=\"zh-Hans\">跨页</td><td>Kuàyè</td></tr><tr class=\"t3v6-category\"><th colspan=\"3\" scope=\"colgroup\">Illustration Styles / 插图风格 / Chātú fēnggé</th></tr><tr><td>Realistic style</td><td lang=\"zh-Hans\">写实风格</td><td>Xiěshí fēnggé</td></tr><tr><td>Cartoon-like style</td><td lang=\"zh-Hans\">卡通风格</td><td>Kǎtōng fēnggé</td></tr><tr><td>Collage style</td><td lang=\"zh-Hans\">拼贴风格</td><td>Pīntiē fēnggé</td></tr><tr><td>Ink-and-line style</td><td lang=\"zh-Hans\">水墨线条风格</td><td>Shuǐmò xiàntiáo fēnggé</td></tr><tr class=\"t3v6-category\"><th colspan=\"3\" scope=\"colgroup\">Visual Elements / 视觉元素 / Shìjué yuánsù</th></tr><tr><td>Different lines</td><td lang=\"zh-Hans\">不同的线条</td><td>Bùtóng de xiàntiáo</td></tr><tr><td>Curved line</td><td lang=\"zh-Hans\">曲线</td><td>Qūxiàn</td></tr><tr><td>Zigzag line</td><td lang=\"zh-Hans\">锯齿线</td><td>Jùchǐxiàn</td></tr><tr><td>Straight line</td><td lang=\"zh-Hans\">直线</td><td>Zhíxiàn</td></tr><tr><td>Dotted line</td><td lang=\"zh-Hans\">虚线</td><td>Xūxiàn</td></tr><tr><td>Warm colours</td><td lang=\"zh-Hans\">暖色</td><td>Nuǎnsè</td></tr><tr><td>Cool colours</td><td lang=\"zh-Hans\">冷色</td><td>Lěngsè</td></tr><tr><td>Composition</td><td lang=\"zh-Hans\">构图</td><td>Gòutú</td></tr></tbody></table></div><h5>Explanatory Notes<br>说明<br>Shuōmíng</h5><div class=\"t3v5-explanation\"><div class=\"t3v2-lang t3v2-en\">Realistic illustrations show recognisable details of people, animals or places.</div><div class=\"t3v2-lang t3v2-zh\">写实插图呈现人物、动物或地方容易辨认的细节。</div><div class=\"t3v2-lang t3v2-py\">Xiěshí chātú chéngxiàn rénwù, dòngwù huò dìfang róngyì biànrèn de xìjié.</div></div><div class=\"t3v5-explanation\"><div class=\"t3v2-lang t3v2-en\">Cartoon-like illustrations often use simplified shapes and expressive features.</div><div class=\"t3v2-lang t3v2-zh\">卡通风格的插图常使用简化的形状和富有表现力的特征。</div><div class=\"t3v2-lang t3v2-py\">Kǎtōng fēnggé de chātú cháng shǐyòng jiǎnhuà de xíngzhuàng hé fùyǒu biǎoxiànlì de tèzhēng.</div></div><div class=\"t3v5-explanation\"><div class=\"t3v2-lang t3v2-en\">Collage illustrations combine pieces of paper or other materials to make an image.</div><div class=\"t3v2-lang t3v2-zh\">拼贴插图将纸张或其他材料组合成图像。</div><div class=\"t3v2-lang t3v2-py\">Pīntiē chātú jiāng zhǐzhāng huò qítā cáiliào zǔhé chéng túxiàng.</div></div><div class=\"t3v5-explanation\"><div class=\"t3v2-lang t3v2-en\">Lines can suggest movement, direction or mood.</div><div class=\"t3v2-lang t3v2-zh\">线条可以表现动作、方向或气氛。</div><div class=\"t3v2-lang t3v2-py\">Xiàntiáo kěyǐ biǎoxiàn dòngzuò, fāngxiàng huò qìfēn.</div></div><div class=\"t3v5-explanation\"><div class=\"t3v2-lang t3v2-en\">Warm and cool colours can influence the mood of an illustration; their meanings depend on context.</div><div class=\"t3v2-lang t3v2-zh\">暖色和冷色可以影响插图的气氛；它们的含义取决于具体情境。</div><div class=\"t3v2-lang t3v2-py\">Nuǎnsè hé lěngsè kěyǐ yǐngxiǎng chātú de qìfēn; tāmen de hányì qǔjué yú jùtǐ qíngjìng.</div></div><div class=\"t3v5-explanation\"><div class=\"t3v2-lang t3v2-en\">Composition is the arrangement of elements in a picture, which guides the reader’s attention.</div><div class=\"t3v2-lang t3v2-zh\">构图是图片中各元素的安排，可以引导读者的注意力。</div><div class=\"t3v2-lang t3v2-py\">Gòutú shì túpiàn zhōng gè yuánsù de ānpái, kěyǐ yǐndǎo dúzhě de zhùyìlì.</div></div></section>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">A picture book has many important parts.</div><div class=\"t3v2-lang t3v2-zh\">图画书有许多重要的部分。</div><div class=\"t3v2-lang t3v2-py\">Túhuàshū Yǒu Xǔduō Zhòngyào de Bùfen.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">These parts help tell the story.</div><div class=\"t3v2-lang t3v2-zh\">这些部分帮助讲述故事。</div><div class=\"t3v2-lang t3v2-py\">Zhèxiē Bùfen Bāngzhù Jiǎngshù Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Some parts are inside the book.</div><div class=\"t3v2-lang t3v2-zh\">有些部分在书里面。</div><div class=\"t3v2-lang t3v2-py\">Yǒuxiē Bùfen Zài Shū Lǐmiàn.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Some parts are outside the book.</div><div class=\"t3v2-lang t3v2-zh\">有些部分在书外面。</div><div class=\"t3v2-lang t3v2-py\">Yǒuxiē Bùfen Zài Shū Wàimiàn.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">What Is Paratext?</div><div class=\"t3v2-lang t3v2-zh\">什么是副文本？</div><div class=\"t3v2-lang t3v2-py\">Shénme shì fù wénběn?</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Paratext includes the parts around the main story.</div><div class=\"t3v2-lang t3v2-zh\">副文本是故事内容以外的部分。</div><div class=\"t3v2-lang t3v2-py\">Fùwénběn Shì Gùshì Nèiróng Yǐwài de Bùfen.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Examples include the cover and title page.</div><div class=\"t3v2-lang t3v2-zh\">例如封面和标题页。</div><div class=\"t3v2-lang t3v2-py\">Lìrú Fēngmiàn Hé Biāotí Yè.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Paratext gives readers information before they read.</div><div class=\"t3v2-lang t3v2-zh\">副文本在阅读前提供信息。</div><div class=\"t3v2-lang t3v2-py\">Fùwénběn Zài Yuèdú Qián Tígōng Xìnxī.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">It creates interest and curiosity.</div><div class=\"t3v2-lang t3v2-zh\">它引起兴趣和好奇心。</div><div class=\"t3v2-lang t3v2-py\">Tā Yǐnqǐ Xìngqù Hé Hǎoqíxīn.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Examples of Paratext</div><div class=\"t3v2-lang t3v2-zh\">副文本示例</div><div class=\"t3v2-lang t3v2-py\">Fù wénběn shìlì</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Paratext may include:</div><div class=\"t3v2-lang t3v2-zh\">副文本可能包括：</div><div class=\"t3v2-lang t3v2-py\">Fùwénběn Kěnéng Bāokuò:</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Front cover</div><div class=\"t3v2-lang t3v2-zh\">封面</div><div class=\"t3v2-lang t3v2-py\">Fēngmiàn</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Back cover</div><div class=\"t3v2-lang t3v2-zh\">封底</div><div class=\"t3v2-lang t3v2-py\">Fēngdǐ</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Title page</div><div class=\"t3v2-lang t3v2-zh\">标题页</div><div class=\"t3v2-lang t3v2-py\">Biāotí Yè</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Endpapers</div><div class=\"t3v2-lang t3v2-zh\">环衬页</div><div class=\"t3v2-lang t3v2-py\">Huánchèn Yè</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Author information</div><div class=\"t3v2-lang t3v2-zh\">作者介绍</div><div class=\"t3v2-lang t3v2-py\">Zuòzhě Jièshào</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">These parts prepare readers for the story.</div><div class=\"t3v2-lang t3v2-zh\">这些部分帮助读者进入故事。</div><div class=\"t3v2-lang t3v2-py\">Zhèxiē Bùfen Bāngzhù Dúzhě Jìnrù Gùshì.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">What Is Peritext?</div><div class=\"t3v2-lang t3v2-zh\">什么是周边文本？</div><div class=\"t3v2-lang t3v2-py\">Shénme shì zhōubiān wénběn?</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Peritext is part of the paratext.</div><div class=\"t3v2-lang t3v2-zh\">周边文本属于副文本的一部分。</div><div class=\"t3v2-lang t3v2-py\">Zhōubiān Wénběn Shǔyú Fùwénběn de Yí Bùfen.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">It is attached to the book itself.</div><div class=\"t3v2-lang t3v2-zh\">它附在书本上。</div><div class=\"t3v2-lang t3v2-py\">Tā Fù Zài Shūběn Shàng.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Examples include the title, cover, and illustrations.</div><div class=\"t3v2-lang t3v2-zh\">例如书名、封面和插图。</div><div class=\"t3v2-lang t3v2-py\">Lìrú Shūmíng, Fēngmiàn Hé Chātú.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Peritext helps readers understand the book.</div><div class=\"t3v2-lang t3v2-zh\">周边文本帮助读者理解书本。</div><div class=\"t3v2-lang t3v2-py\">Zhōubiān Wénběn Bāngzhù Dúzhě Lǐjiě Shūběn.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Double-Page Spread</div><div class=\"t3v2-lang t3v2-zh\">跨页</div><div class=\"t3v2-lang t3v2-py\">Kuàyè</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">A double-page spread uses two pages together.</div><div class=\"t3v2-lang t3v2-zh\">跨页设计使用左右两页来呈现内容。</div><div class=\"t3v2-lang t3v2-py\">Kuàyè Shèjì Shǐyòng Zuǒyòu Liǎng Yè Lái Chéngxiàn Nèiróng.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The picture continues across both pages.</div><div class=\"t3v2-lang t3v2-zh\">图片横跨两页。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Héngkuà Liǎng Yè.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">This creates a bigger visual effect.</div><div class=\"t3v2-lang t3v2-zh\">这样可以创造更大的视觉效果。</div><div class=\"t3v2-lang t3v2-py\">Zhèyàng Kěyǐ Chuàngzào Gèng Dà de Shìjué Xiàoguǒ.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">It makes the story more exciting.</div><div class=\"t3v2-lang t3v2-zh\">它让故事更加精彩。</div><div class=\"t3v2-lang t3v2-py\">Tā Ràng Gùshì Gèngjiā Jīngcǎi.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Why Do Authors Use Double-Page Spreads?</div><div class=\"t3v2-lang t3v2-zh\">作者为何使用跨页版面？</div><div class=\"t3v2-lang t3v2-py\">Zuòzhě wéi hé shǐyòng kuà yè bǎnmiàn?</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Large pictures show important events.</div><div class=\"t3v2-lang t3v2-zh\">大图片展示重要情节。</div><div class=\"t3v2-lang t3v2-py\">Dà Túpiàn Zhǎnshì Zhòngyào Qíngjié.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Readers can see more details.</div><div class=\"t3v2-lang t3v2-zh\">读者可以看到更多细节。</div><div class=\"t3v2-lang t3v2-py\">Dúzhě Kěyǐ Kàndào Gèng Duō Xìjié.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Children become more interested.</div><div class=\"t3v2-lang t3v2-zh\">孩子更有兴趣阅读。</div><div class=\"t3v2-lang t3v2-py\">Háizi Gèng Yǒu Xìngqù Yuèdú.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The story feels more real.</div><div class=\"t3v2-lang t3v2-zh\">故事显得更加真实。</div><div class=\"t3v2-lang t3v2-py\">Gùshì Xiǎnde Gèngjiā Zhēnshí.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Why Are These Features Important?</div><div class=\"t3v2-lang t3v2-zh\">为什么这些功能很重要？</div><div class=\"t3v2-lang t3v2-py\">Wèishéme zhèxiē gōngnéng hěn zhòngyào?</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Every part of the book has a purpose.</div><div class=\"t3v2-lang t3v2-zh\">书本的每一个部分都有作用。</div><div class=\"t3v2-lang t3v2-py\">Shūběn de Měi Yí Gè Bùfen Dōu Yǒu Zuòyòng.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The cover attracts readers.</div><div class=\"t3v2-lang t3v2-zh\">封面吸引读者。</div><div class=\"t3v2-lang t3v2-py\">Fēngmiàn Xīyǐn Dúzhě.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The pictures help tell the story.</div><div class=\"t3v2-lang t3v2-zh\">图片帮助讲故事。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Bāngzhù Jiǎng Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The design makes reading enjoyable.</div><div class=\"t3v2-lang t3v2-zh\">设计让阅读更加有趣。</div><div class=\"t3v2-lang t3v2-py\">Shèjì Ràng Yuèdú Gèngjiā Yǒuqù.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Teacher's Role</div><div class=\"t3v2-lang t3v2-zh\">教师的角色</div><div class=\"t3v2-lang t3v2-py\">Jiàoshī de juésè</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Teachers should explore every part of the picture book.</div><div class=\"t3v2-lang t3v2-zh\">教师应该探索图画书的每一个部分。</div><div class=\"t3v2-lang t3v2-py\">Jiàoshī Yīnggāi Tànsuǒ Túhuàshū de Měi Yí Gè Bùfen.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Ask children questions before reading.</div><div class=\"t3v2-lang t3v2-zh\">阅读前向孩子提问。</div><div class=\"t3v2-lang t3v2-py\">Yuèdú Qián Xiàng Háizi Tíwèn.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Talk about the cover and pictures.</div><div class=\"t3v2-lang t3v2-zh\">讨论封面和图片。</div><div class=\"t3v2-lang t3v2-py\">Tǎolùn Fēngmiàn Hé Túpiàn.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Help children notice small details.</div><div class=\"t3v2-lang t3v2-zh\">帮助孩子观察细节。</div><div class=\"t3v2-lang t3v2-py\">Bāngzhù Háizi Guānchá Xìjié.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Summary</div><div class=\"t3v2-lang t3v2-zh\">总结</div><div class=\"t3v2-lang t3v2-py\">Zǒngjié</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Picture books are more than stories.</div><div class=\"t3v2-lang t3v2-zh\">图画书不仅仅是故事。</div><div class=\"t3v2-lang t3v2-py\">Túhuàshū Bù Jǐnjǐn Shì Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Every part helps children understand the book.</div><div class=\"t3v2-lang t3v2-zh\">每一个部分都帮助孩子理解书本。</div><div class=\"t3v2-lang t3v2-py\">Měi Yí Gè Bùfen Dōu Bāngzhù Háizi Lǐjiě Shūběn.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Good design makes reading meaningful.</div><div class=\"t3v2-lang t3v2-zh\">好的设计让阅读更有意义。</div><div class=\"t3v2-lang t3v2-py\">Hǎo de Shèjì Ràng Yuèdú Gèng Yǒu Yìyì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Teachers should guide children to notice these features.</div><div class=\"t3v2-lang t3v2-zh\">教师应该引导孩子观察这些特点。</div><div class=\"t3v2-lang t3v2-py\">Jiàoshī Yīnggāi Yǐndǎo Háizi Guānchá Zhèxiē Tèdiǎn.</div></div>\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 1: Picture Book Treasure Hunt</div><div class=\"t3v2-lang t3v2-zh\">活动一：图画书寻宝游戏</div><div class=\"t3v2-lang t3v2-py\">Huódòng Yī: Túhuàshū Xúnbǎo Yóuxì</div></h4>\n<div class=\"t3v2-body t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Find different parts of a picture book.</div><div class=\"t3v2-lang t3v2-zh\">寻找图画书的不同部分。</div><div class=\"t3v2-lang t3v2-py\">Xúnzhǎo Túhuàshū de Bùtóng Bùfen.</div></div>\n<div class=\"t3v2-body t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Several picture books</div><div class=\"t3v2-lang t3v2-zh\">几本图画书</div><div class=\"t3v2-lang t3v2-py\">Jǐ Běn Túhuàshū</div></div>\n<div class=\"t3v2-body t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Work in groups of three.</div><div class=\"t3v2-lang t3v2-zh\">三人一组。</div><div class=\"t3v2-lang t3v2-py\">Sān Rén Yì Zǔ.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Find the following:</div><div class=\"t3v2-lang t3v2-zh\">寻找以下部分：</div><div class=\"t3v2-lang t3v2-py\">Xúnzhǎo Yǐxià Bùfen:</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Front cover</div><div class=\"t3v2-lang t3v2-zh\">封面</div><div class=\"t3v2-lang t3v2-py\">Fēngmiàn</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Back cover</div><div class=\"t3v2-lang t3v2-zh\">封底</div><div class=\"t3v2-lang t3v2-py\">Fēngdǐ</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Title page</div><div class=\"t3v2-lang t3v2-zh\">标题页</div><div class=\"t3v2-lang t3v2-py\">Biāotí Yè</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Endpapers</div><div class=\"t3v2-lang t3v2-zh\">环衬页</div><div class=\"t3v2-lang t3v2-py\">Huánchèn Yè</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Double-page spread</div><div class=\"t3v2-lang t3v2-zh\">跨页设计</div><div class=\"t3v2-lang t3v2-py\">Kuàyè Shèjì</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Explain why each part is important.</div><div class=\"t3v2-lang t3v2-zh\">说明每个部分的重要性。</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng Měi Gè Bùfen de Zhòngyàoxìng.</div></div>\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 2: Before Reading Detective</div><div class=\"t3v2-lang t3v2-zh\">活动二：阅读前小侦探</div><div class=\"t3v2-lang t3v2-py\">Huódòng Èr: Yuèdú Qián Xiǎo Zhēntàn</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Use clues from a book cover to predict what the story might be about.</div><div class=\"t3v2-lang t3v2-zh\">根据图书封面的线索，预测故事可能讲述什么。</div><div class=\"t3v2-lang t3v2-py\">Gēnjù túshū fēngmiàn de xiànsuǒ, yùcè gùshì kěnéng jiǎngshù shénme.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">One picture book for each group.</div><div class=\"t3v2-lang t3v2-zh\">每组一本图画书。</div><div class=\"t3v2-lang t3v2-py\">Měi zǔ yì běn túhuàshū.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Work in groups of three.</div><div class=\"t3v2-lang t3v2-zh\">1. 三人一组。</div><div class=\"t3v2-lang t3v2-py\">1. Sān rén yì zǔ.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Look only at the front cover. Do not open the book yet.</div><div class=\"t3v2-lang t3v2-zh\">2. 只观察封面，暂时不要打开书本。</div><div class=\"t3v2-lang t3v2-py\">2. Zhǐ guānchá fēngmiàn, zànshí búyào dǎkāi shūběn.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Discuss: What might the story be about? Who might the characters be? Where might the story happen?</div><div class=\"t3v2-lang t3v2-zh\">3. 讨论：故事可能讲什么？故事人物可能是谁？故事可能发生在哪里？</div><div class=\"t3v2-lang t3v2-py\">3. Tǎolùn: Gùshì kěnéng jiǎng shénme? Gùshì rénwù kěnéng shì shéi? Gùshì kěnéng fāshēng zài nǎlǐ?</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Open the book and read the story. Compare your predictions with the actual story.</div><div class=\"t3v2-lang t3v2-zh\">4. 打开书本，阅读故事，并比较你们的预测与实际内容。</div><div class=\"t3v2-lang t3v2-py\">4. Dǎkāi shūběn, yuèdú gùshì, bìng bǐjiào nǐmen de yùcè yǔ shíjì nèiróng.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Share one prediction that was correct or different.</div><div class=\"t3v2-lang t3v2-zh\">5. 分享一个正确或与故事内容不同的预测。</div><div class=\"t3v2-lang t3v2-py\">5. Fēnxiǎng yí gè zhèngquè huò yǔ gùshì nèiróng bùtóng de yùcè.</div></div>\n\n\n\n\n\n\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 3: Design a New Cover</div><div class=\"t3v2-lang t3v2-zh\">活动三：设计新的封面</div><div class=\"t3v2-lang t3v2-py\">Huódòng Sān: Shèjì Xīn de Fēngmiàn</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Design a picture-book cover that gives readers clues about the story.</div><div class=\"t3v2-lang t3v2-zh\">设计一个能让读者了解故事线索的图画书封面。</div><div class=\"t3v2-lang t3v2-py\">Shèjì yí gè néng ràng dúzhě liǎojiě gùshì xiànsuǒ de túhuàshū fēngmiàn.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">A familiar picture book, drawing paper, pencils and colouring materials.</div><div class=\"t3v2-lang t3v2-zh\">一本熟悉的图画书、画纸、铅笔和彩色绘画工具。</div><div class=\"t3v2-lang t3v2-py\">Yì běn shúxī de túhuàshū, huàzhǐ, qiānbǐ hé cǎisè huìhuà gōngjù.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Choose a picture book you know well.</div><div class=\"t3v2-lang t3v2-zh\">1. 选择一本你熟悉的图画书。</div><div class=\"t3v2-lang t3v2-py\">1. Xuǎnzé yì běn nǐ shúxī de túhuàshū.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Think about the main characters, setting and important events.</div><div class=\"t3v2-lang t3v2-zh\">2. 想一想主要人物、故事背景和重要事件。</div><div class=\"t3v2-lang t3v2-py\">2. Xiǎng yi xiǎng zhǔyào rénwù, gùshì bèijǐng hé zhòngyào shìjiàn.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Draw a new front cover for the book.</div><div class=\"t3v2-lang t3v2-zh\">3. 为这本书设计一个新的封面。</div><div class=\"t3v2-lang t3v2-py\">3. Wèi zhè běn shū shèjì yí gè xīn de fēngmiàn.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Include the book title, an illustration and the author’s name.</div><div class=\"t3v2-lang t3v2-zh\">4. 包括书名、插图和作者姓名。</div><div class=\"t3v2-lang t3v2-py\">4. Bāokuò shūmíng, chātú hé zuòzhě xìngmíng.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Present your new cover to the class. Explain how your illustration helps readers understand the story.</div><div class=\"t3v2-lang t3v2-zh\">5. 向全班展示你的新封面，并解释插图如何帮助读者理解故事。</div><div class=\"t3v2-lang t3v2-py\">5. Xiàng quánbān zhǎnshì nǐ de xīn fēngmiàn, bìng jiěshì chātú rúhé bāngzhù dúzhě lǐjiě gùshì.</div></div>\n\n\n\n\n\n\n\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 4: Double-Page Story</div><div class=\"t3v2-lang t3v2-zh\">活动四：跨页故事设计</div><div class=\"t3v2-lang t3v2-py\">Huódòng Sì: Kuàyè Gùshì Shèjì</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Create a double-page spread that uses pictures and words to tell a story.</div><div class=\"t3v2-lang t3v2-zh\">设计一个利用图画和文字讲故事的跨页。</div><div class=\"t3v2-lang t3v2-py\">Shèjì yí gè lìyòng túhuà hé wénzì jiǎng gùshì de kuàyè.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Two sheets of drawing paper, pencils and colouring materials.</div><div class=\"t3v2-lang t3v2-zh\">两张画纸、铅笔和彩色绘画工具。</div><div class=\"t3v2-lang t3v2-py\">Liǎng zhāng huàzhǐ, qiānbǐ hé cǎisè huìhuà gōngjù.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Work in pairs.</div><div class=\"t3v2-lang t3v2-zh\">1. 两人一组。</div><div class=\"t3v2-lang t3v2-py\">1. Liǎng rén yì zǔ.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Place two sheets of paper side by side to represent two facing pages of a book.</div><div class=\"t3v2-lang t3v2-zh\">2. 将两张纸并排放置，代表书本中相对的两页。</div><div class=\"t3v2-lang t3v2-py\">2. Jiāng liǎng zhāng zhǐ bìngpái fàngzhì, dàibiǎo shūběn zhōng xiāngduì de liǎng yè.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Choose one scene from a simple story.</div><div class=\"t3v2-lang t3v2-zh\">3. 从一个简单的故事中选择一个场景。</div><div class=\"t3v2-lang t3v2-py\">3. Cóng yí gè jiǎndān de gùshì zhōng xuǎnzé yí gè chǎngjǐng.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Draw one large illustration across both pages.</div><div class=\"t3v2-lang t3v2-zh\">4. 在两页上画一幅跨页大插图。</div><div class=\"t3v2-lang t3v2-py\">4. Zài liǎng yè shàng huà yì fú kuàyè dà chātú.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Write two or three simple sentences to accompany the illustration.</div><div class=\"t3v2-lang t3v2-zh\">5. 写两到三个简单的句子来配合插图。</div><div class=\"t3v2-lang t3v2-py\">5. Xiě liǎng dào sān gè jiǎndān de jùzi lái pèihé chātú.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">6. Present your work and explain why you chose a double-page spread instead of a single-page illustration.</div><div class=\"t3v2-lang t3v2-zh\">6. 展示你们的作品，并解释为什么选择跨页设计，而不是单页插图。</div><div class=\"t3v2-lang t3v2-py\">6. Zhǎnshì nǐmen de zuòpǐn, bìng jiěshì wèishénme xuǎnzé kuàyè shèjì, ér bú shì dānyè chātú.</div></div>\n\n\n\n\n\n<h3 class=\"t3v2-section\"><div class=\"t3v2-lang t3v2-en\">3.2 Evaluating Illustration</div><div class=\"t3v2-lang t3v2-zh\">3.2 评估插图</div><div class=\"t3v2-lang t3v2-py\">3.2 Pínggū Chātú</div></h3>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">What Is an Illustration?</div><div class=\"t3v2-lang t3v2-zh\">什么是插图？</div><div class=\"t3v2-lang t3v2-py\">Shénme Shì Chātú?</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">An illustration is a picture in a book.</div><div class=\"t3v2-lang t3v2-zh\">插图是书中的图片。</div><div class=\"t3v2-lang t3v2-py\">Chātú Shì Shū Zhōng de Túpiàn.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Illustrations help tell the story.</div><div class=\"t3v2-lang t3v2-zh\">插图帮助讲述故事。</div><div class=\"t3v2-lang t3v2-py\">Chātú Bāngzhù Jiǎngshù Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Children learn from both words and pictures.</div><div class=\"t3v2-lang t3v2-zh\">孩子通过文字和图片学习。</div><div class=\"t3v2-lang t3v2-py\">Háizi Tōngguò Wénzì Hé Túpiàn Xuéxí.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Good illustrations make reading more enjoyable.</div><div class=\"t3v2-lang t3v2-zh\">好的插图让阅读更加有趣。</div><div class=\"t3v2-lang t3v2-py\">Hǎo de Chātú Ràng Yuèdú Gèngjiā Yǒuqù.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Why Are Illustrations Important?</div><div class=\"t3v2-lang t3v2-zh\">为什么插图很重要？</div><div class=\"t3v2-lang t3v2-py\">Wèishéme chātú hěn zhòngyào?</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Illustrations attract children's attention.</div><div class=\"t3v2-lang t3v2-zh\">插图吸引孩子的注意力。</div><div class=\"t3v2-lang t3v2-py\">Chātú Xīyǐn Háizi de Zhùyìlì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">They help children understand the story.</div><div class=\"t3v2-lang t3v2-zh\">它们帮助孩子理解故事。</div><div class=\"t3v2-lang t3v2-py\">Tāmen Bāngzhù Háizi Lǐjiě Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Illustrations show feelings and actions.</div><div class=\"t3v2-lang t3v2-zh\">插图表现人物的情感和动作。</div><div class=\"t3v2-lang t3v2-py\">Chātú Biǎoxiàn Rénwù de Qínggǎn Hé Dòngzuò.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Children can enjoy the story even before they can read.</div><div class=\"t3v2-lang t3v2-zh\">孩子还不会阅读时，也能欣赏故事。</div><div class=\"t3v2-lang t3v2-py\">Háizi Hái Bú Huì Yuèdú Shí, Yě Néng Xīnshǎng Gùshì.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Media</div><div class=\"t3v2-lang t3v2-zh\">媒材</div><div class=\"t3v2-lang t3v2-py\">Méicáiǐ</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Media means the materials used to create illustrations.</div><div class=\"t3v2-lang t3v2-zh\">媒材是指创作插图所使用的材料。</div><div class=\"t3v2-lang t3v2-py\">Méicái Shì Zhǐ Chuàngzuò Chātú Suǒ Shǐyòng de Cáiliào.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Different media create different effects.</div><div class=\"t3v2-lang t3v2-zh\">不同媒材创造不同效果。</div><div class=\"t3v2-lang t3v2-py\">Bùtóng Méicái Chuàngzào Bùtóng Xiàoguǒ.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Examples include:</div><div class=\"t3v2-lang t3v2-zh\">例如：</div><div class=\"t3v2-lang t3v2-py\">Lìrú:</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Watercolour</div><div class=\"t3v2-lang t3v2-zh\">水彩</div><div class=\"t3v2-lang t3v2-py\">Shuǐcǎi</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Pencil</div><div class=\"t3v2-lang t3v2-zh\">铅笔</div><div class=\"t3v2-lang t3v2-py\">Qiānbǐ</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Ink</div><div class=\"t3v2-lang t3v2-zh\">墨水</div><div class=\"t3v2-lang t3v2-py\">Mòshuǐ</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Collage</div><div class=\"t3v2-lang t3v2-zh\">拼贴</div><div class=\"t3v2-lang t3v2-py\">Pīntiē</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Digital art</div><div class=\"t3v2-lang t3v2-zh\">数码绘画</div><div class=\"t3v2-lang t3v2-py\">Shùmǎ Huìhuà</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Style</div><div class=\"t3v2-lang t3v2-zh\">风格</div><div class=\"t3v2-lang t3v2-py\">Fēnggé</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Style is the artist's way of drawing.</div><div class=\"t3v2-lang t3v2-zh\">风格是画家的绘画方式。</div><div class=\"t3v2-lang t3v2-py\">Fēnggé Shì Huàjiā de Huìhuà Fāngshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Some illustrations look realistic.</div><div class=\"t3v2-lang t3v2-zh\">有些插图看起来很真实。</div><div class=\"t3v2-lang t3v2-py\">Yǒuxiē Chātú Kàn Qǐlái Hěn Zhēnshí.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Some look simple and cartoon-like.</div><div class=\"t3v2-lang t3v2-zh\">有些插图简单，像卡通。</div><div class=\"t3v2-lang t3v2-py\">Yǒuxiē Chātú Jiǎndān, Xiàng Kǎtōng.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Some are colourful and imaginative.</div><div class=\"t3v2-lang t3v2-zh\">有些插图色彩丰富，富有想象力。</div><div class=\"t3v2-lang t3v2-py\">Yǒuxiē Chātú Sècǎi Fēngfù, Fùyǒu Xiǎngxiànglì.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Line</div><div class=\"t3v2-lang t3v2-zh\">线条</div><div class=\"t3v2-lang t3v2-py\">Xiàntiáo</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Lines help create shapes and movement.</div><div class=\"t3v2-lang t3v2-zh\">线条帮助形成形状和动作。</div><div class=\"t3v2-lang t3v2-py\">Xiàntiáo Bāngzhù Xíngchéng Xíngzhuàng Hé Dòngzuò.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Thick lines can show strength.</div><div class=\"t3v2-lang t3v2-zh\">粗线条可以表现力量。</div><div class=\"t3v2-lang t3v2-py\">Cū Xiàntiáo Kěyǐ Biǎoxiàn Lìliàng.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Thin lines can look soft and gentle.</div><div class=\"t3v2-lang t3v2-zh\">细线条显得柔和。</div><div class=\"t3v2-lang t3v2-py\">Xì Xiàntiáo Xiǎnde Róuhé.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Curved lines show movement.</div><div class=\"t3v2-lang t3v2-zh\">弯曲线条表现动作。</div><div class=\"t3v2-lang t3v2-py\">Wānqū Xiàntiáo Biǎoxiàn Dòngzuò.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Colour</div><div class=\"t3v2-lang t3v2-zh\">颜色</div><div class=\"t3v2-lang t3v2-py\">Yánsè</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Colours create mood.</div><div class=\"t3v2-lang t3v2-zh\">颜色营造气氛。</div><div class=\"t3v2-lang t3v2-py\">Yánsè Yíngzào Qìfēn.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Bright colours show happiness.</div><div class=\"t3v2-lang t3v2-zh\">明亮的颜色表现快乐。</div><div class=\"t3v2-lang t3v2-py\">Míngliàng de Yánsè Biǎoxiàn Kuàilè.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Dark colours may show sadness or mystery.</div><div class=\"t3v2-lang t3v2-zh\">深色可能表现悲伤或神秘。</div><div class=\"t3v2-lang t3v2-py\">Shēnsè Kěnéng Biǎoxiàn Bēishāng Huò Shénmì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Warm colours feel energetic.</div><div class=\"t3v2-lang t3v2-zh\">暖色让人感觉充满活力。</div><div class=\"t3v2-lang t3v2-py\">Nuǎnsè Ràng Rén Gǎnjué Chōngmǎn Huólì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Cool colours feel calm.</div><div class=\"t3v2-lang t3v2-zh\">冷色让人感觉平静。</div><div class=\"t3v2-lang t3v2-py\">Lěngsè Ràng Rén Gǎnjué Píngjìng.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Composition</div><div class=\"t3v2-lang t3v2-zh\">构图</div><div class=\"t3v2-lang t3v2-py\">Gòutú</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Composition means how pictures are arranged.</div><div class=\"t3v2-lang t3v2-zh\">构图是图片的排列方式。</div><div class=\"t3v2-lang t3v2-py\">Gòutú Shì Túpiàn de Páiliè Fāngshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The main character should be easy to see.</div><div class=\"t3v2-lang t3v2-zh\">主角应该容易看到。</div><div class=\"t3v2-lang t3v2-py\">Zhǔjué Yīnggāi Róngyì Kàndào.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The picture should guide the reader's eyes.</div><div class=\"t3v2-lang t3v2-zh\">图片应该引导读者的视线。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Yīnggāi Yǐndǎo Dúzhě de Shìxiàn.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">A balanced picture looks comfortable.</div><div class=\"t3v2-lang t3v2-zh\">平衡的画面让人感觉舒服。</div><div class=\"t3v2-lang t3v2-py\">Pínghéng de Huàmiàn Ràng Rén Gǎnjué Shūfu.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Questions for Evaluating Illustrations</div><div class=\"t3v2-lang t3v2-zh\">评估插图的问题</div><div class=\"t3v2-lang t3v2-py\">Pínggū chātú de wèntí</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Ask yourself:</div><div class=\"t3v2-lang t3v2-zh\">问问自己：</div><div class=\"t3v2-lang t3v2-py\">Wèn Wen Zìjǐ:</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Are the illustrations attractive?</div><div class=\"t3v2-lang t3v2-zh\">插图漂亮吗？</div><div class=\"t3v2-lang t3v2-py\">Chātú Piàoliang Ma?</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Do the pictures match the story?</div><div class=\"t3v2-lang t3v2-zh\">图片符合故事吗？</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Fúhé Gùshì Ma?</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Do the colours fit the mood?</div><div class=\"t3v2-lang t3v2-zh\">颜色符合故事气氛吗？</div><div class=\"t3v2-lang t3v2-py\">Yánsè Fúhé Gùshì Qìfēn Ma?</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Can children understand the pictures?</div><div class=\"t3v2-lang t3v2-zh\">孩子容易理解图片吗？</div><div class=\"t3v2-lang t3v2-py\">Háizi Róngyì Lǐjiě Túpiàn Ma?</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Example 1</div><div class=\"t3v2-lang t3v2-zh\">示例 1</div><div class=\"t3v2-lang t3v2-py\">Shìlì 1</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Book A uses watercolour illustrations.</div><div class=\"t3v2-lang t3v2-zh\">图书A使用水彩插图。</div><div class=\"t3v2-lang t3v2-py\">Túshū A Shǐyòng Shuǐcǎi Chātú.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The colours are soft and warm.</div><div class=\"t3v2-lang t3v2-zh\">颜色柔和温暖。</div><div class=\"t3v2-lang t3v2-py\">Yánsè Róuhé Wēnnuǎn.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The pictures create a peaceful feeling.</div><div class=\"t3v2-lang t3v2-zh\">图片营造宁静的感觉。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Yíngzào Níngjìng de Gǎnjué.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">This style is suitable for bedtime stories.</div><div class=\"t3v2-lang t3v2-zh\">这种风格适合睡前故事。</div><div class=\"t3v2-lang t3v2-py\">Zhè Zhǒng Fēnggé Shìhé Shuìqián Gùshì.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Example 2</div><div class=\"t3v2-lang t3v2-zh\">示例 2</div><div class=\"t3v2-lang t3v2-py\">Shìlì 2</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Book B uses digital illustrations.</div><div class=\"t3v2-lang t3v2-zh\">图书B使用数码插图。</div><div class=\"t3v2-lang t3v2-py\">Túshū B Shǐyòng Shùmǎ Chātú.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The colours are bright and exciting.</div><div class=\"t3v2-lang t3v2-zh\">颜色鲜艳而有活力。</div><div class=\"t3v2-lang t3v2-py\">Yánsè Xiānyàn Ér Yǒu Huólì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The characters look funny.</div><div class=\"t3v2-lang t3v2-zh\">人物看起来很有趣。</div><div class=\"t3v2-lang t3v2-py\">Rénwù Kàn Qǐlái Hěn Yǒuqù.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">This style is suitable for humorous stories.</div><div class=\"t3v2-lang t3v2-zh\">这种风格适合幽默故事。</div><div class=\"t3v2-lang t3v2-py\">Zhè Zhǒng Fēnggé Shìhé Yōumò Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Illustrations are an important part of picture books.</div><div class=\"t3v2-lang t3v2-zh\">插图是图画书的重要部分。</div><div class=\"t3v2-lang t3v2-py\">Chātú Shì Túhuàshū de Zhòngyào Bùfen.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Teachers should evaluate media, style, line, colour and composition.</div><div class=\"t3v2-lang t3v2-zh\">教师应该评估媒材、风格、线条、颜色和构图。</div><div class=\"t3v2-lang t3v2-py\">Jiàoshī Yīnggāi Pínggū Méicái, Fēnggé, Xiàntiáo, Yánsè Hé Gòutú.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Good illustrations help children understand and enjoy stories.</div><div class=\"t3v2-lang t3v2-zh\">好的插图帮助孩子理解并欣赏故事。</div><div class=\"t3v2-lang t3v2-py\">Hǎo de Chātú Bāngzhù Háizi Lǐjiě Bìng Xīnshǎng Gùshì.</div></div>\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 1: Illustration Detective</div><div class=\"t3v2-lang t3v2-zh\">活动一：插图小侦探</div><div class=\"t3v2-lang t3v2-py\">Huódòng Yī: Chātú Xiǎo Zhēntàn</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Identify and compare different illustration styles in picture books.</div><div class=\"t3v2-lang t3v2-zh\">辨认并比较图画书中不同的插图风格。</div><div class=\"t3v2-lang t3v2-py\">Biànrèn bìng bǐjiào túhuàshū zhōng bùtóng de chātú fēnggé.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Three picture books with different illustration styles, and a comparison worksheet.</div><div class=\"t3v2-lang t3v2-zh\">三本插图风格不同的图画书，以及一张比较记录表。</div><div class=\"t3v2-lang t3v2-py\">Sān běn chātú fēnggé bùtóng de túhuàshū, yǐjí yì zhāng bǐjiào jìlù biǎo.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Work in small groups.</div><div class=\"t3v2-lang t3v2-zh\">1. 小组合作。</div><div class=\"t3v2-lang t3v2-py\">1. Xiǎozǔ hézuò.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Look at illustrations from three different picture books.</div><div class=\"t3v2-lang t3v2-zh\">2. 观察三本不同图画书中的插图。</div><div class=\"t3v2-lang t3v2-py\">2. Guānchá sān běn bùtóng túhuàshū zhōng de chātú.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Identify the illustration style used in each book, such as realistic or cartoon-like.</div><div class=\"t3v2-lang t3v2-zh\">3. 辨认每本书的插图风格，例如写实风格或卡通风格。</div><div class=\"t3v2-lang t3v2-py\">3. Biànrèn měi běn shū de chātú fēnggé, lìrú xiěshí fēnggé huò kǎtōng fēnggé.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Complete a comparison table. Record the illustration style, colours and lines used in each book.</div><div class=\"t3v2-lang t3v2-zh\">4. 完成比较表，记录每本书的插图风格、颜色和线条。</div><div class=\"t3v2-lang t3v2-py\">4. Wánchéng bǐjiào biǎo, jìlù měi běn shū de chātú fēnggé, yánsè hé xiàntiáo.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Present your findings and explain how the illustrations help tell each story.</div><div class=\"t3v2-lang t3v2-zh\">5. 展示你们的发现，并解释插图如何帮助讲述故事。</div><div class=\"t3v2-lang t3v2-py\">5. Zhǎnshì nǐmen de fāxiàn, bìng jiěshì chātú rúhé bāngzhù jiǎngshù gùshì.</div></div>\n\n\n\n\n\n\n\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 2: Colour and Emotion</div><div class=\"t3v2-lang t3v2-zh\">活动二：颜色与情绪</div><div class=\"t3v2-lang t3v2-py\">Huódòng Èr: Yánsè Yǔ Qíngxù</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Explore how colours can create different emotions and moods in illustrations.</div><div class=\"t3v2-lang t3v2-zh\">探索颜色如何在插图中表达不同的情绪和气氛。</div><div class=\"t3v2-lang t3v2-py\">Tànsuǒ yánsè rúhé zài chātú zhōng biǎodá bùtóng de qíngxù hé qìfēn.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Drawing paper, coloured pencils or markers.</div><div class=\"t3v2-lang t3v2-zh\">画纸、彩色铅笔或彩色笔。</div><div class=\"t3v2-lang t3v2-py\">Huàzhǐ, cǎisè qiānbǐ huò cǎisè bǐ.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Draw a scene that shows happiness.</div><div class=\"t3v2-lang t3v2-zh\">1. 画一个表现快乐的场景。</div><div class=\"t3v2-lang t3v2-py\">1. Huà yí gè biǎoxiàn kuàilè de chǎngjǐng.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Draw another scene that shows sadness.</div><div class=\"t3v2-lang t3v2-zh\">2. 再画一个表现悲伤的场景。</div><div class=\"t3v2-lang t3v2-py\">2. Zài huà yí gè biǎoxiàn bēishāng de chǎngjǐng.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Choose colours that help express each emotion.</div><div class=\"t3v2-lang t3v2-zh\">3. 选择能够表达每种情绪的颜色。</div><div class=\"t3v2-lang t3v2-py\">3. Xuǎnzé nénggòu biǎodá měi zhǒng qíngxù de yánsè.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Compare the colours used in both drawings.</div><div class=\"t3v2-lang t3v2-zh\">4. 比较两幅画中使用的颜色。</div><div class=\"t3v2-lang t3v2-py\">4. Bǐjiào liǎng fú huà zhōng shǐyòng de yánsè.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Explain how your colour choices help create different moods.</div><div class=\"t3v2-lang t3v2-zh\">5. 解释你选择的颜色如何营造不同的气氛。</div><div class=\"t3v2-lang t3v2-py\">5. Jiěshì nǐ xuǎnzé de yánsè rúhé yíngzào bùtóng de qìfēn.</div></div>\n\n\n\n\n\n\n\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 3: Compare Two Illustrations</div><div class=\"t3v2-lang t3v2-zh\">活动三：比较两幅插图</div><div class=\"t3v2-lang t3v2-py\">Huódòng Sān: Bǐjiào Liǎng Fú Chātú</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Compare how different illustrators use media, style, lines, colours and composition.</div><div class=\"t3v2-lang t3v2-zh\">比较不同插画家如何运用媒材、风格、线条、颜色和构图。</div><div class=\"t3v2-lang t3v2-py\">Bǐjiào bùtóng chāhuàjiā rúhé yùnyòng méicái, fēnggé, xiàntiáo, yánsè hé gòutú.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Two picture books with different illustration styles, and a comparison worksheet.</div><div class=\"t3v2-lang t3v2-zh\">两本插图风格不同的图画书，以及一张比较记录表。</div><div class=\"t3v2-lang t3v2-py\">Liǎng běn chātú fēnggé bùtóng de túhuàshū, yǐjí yì zhāng bǐjiào jìlù biǎo.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Work in pairs.</div><div class=\"t3v2-lang t3v2-zh\">1. 两人一组。</div><div class=\"t3v2-lang t3v2-py\">1. Liǎng rén yì zǔ.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Choose one illustration from each picture book.</div><div class=\"t3v2-lang t3v2-zh\">2. 从每本图画书中各选择一幅插图。</div><div class=\"t3v2-lang t3v2-py\">2. Cóng měi běn túhuàshū zhōng gè xuǎnzé yì fú chātú.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Compare the two illustrations using media, style, line, colour and composition.</div><div class=\"t3v2-lang t3v2-zh\">3. 根据媒材、风格、线条、颜色和构图比较两幅插图。</div><div class=\"t3v2-lang t3v2-py\">3. Gēnjù méicái, fēnggé, xiàntiáo, yánsè hé gòutú bǐjiào liǎng fú chātú.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Record at least two similarities and two differences.</div><div class=\"t3v2-lang t3v2-zh\">4. 记录至少两个相同点和两个不同点。</div><div class=\"t3v2-lang t3v2-py\">4. Jìlù zhìshǎo liǎng gè xiāngtóng diǎn hé liǎng gè bùtóng diǎn.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Choose the illustration you prefer. Explain your choice using examples from the pictures.</div><div class=\"t3v2-lang t3v2-zh\">5. 选择你比较喜欢的插图，并根据图片中的例子解释原因。</div><div class=\"t3v2-lang t3v2-py\">5. Xuǎnzé nǐ bǐjiào xǐhuān de chātú, bìng gēnjù túpiàn zhōng de lìzi jiěshì yuányīn.</div></div>\n\n\n\n\n\n\n\n\n\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 4: Become an Illustrator</div><div class=\"t3v2-lang t3v2-zh\">活动四：成为小插画家</div><div class=\"t3v2-lang t3v2-py\">Huódòng Sì: Chéngwéi Xiǎo Chāhuàjiā</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Create an illustration using suitable colours, styles and composition to support a story.</div><div class=\"t3v2-lang t3v2-zh\">运用合适的颜色、风格和构图创作插图，以帮助讲述故事。</div><div class=\"t3v2-lang t3v2-py\">Yùnyòng héshì de yánsè, fēnggé hé gòutú chuàngzuò chātú, yǐ bāngzhù jiǎngshù gùshì.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">A short story, drawing paper, pencils and colouring materials.</div><div class=\"t3v2-lang t3v2-zh\">一个短故事、画纸、铅笔和彩色绘画工具。</div><div class=\"t3v2-lang t3v2-py\">Yí gè duǎn gùshì, huàzhǐ, qiānbǐ hé cǎisè huìhuà gōngjù.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Choose a short story.</div><div class=\"t3v2-lang t3v2-zh\">1. 选择一个短故事。</div><div class=\"t3v2-lang t3v2-py\">1. Xuǎnzé yí gè duǎn gùshì.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Select one important scene from the story.</div><div class=\"t3v2-lang t3v2-zh\">2. 从故事中选择一个重要场景。</div><div class=\"t3v2-lang t3v2-py\">2. Cóng gùshì zhōng xuǎnzé yí gè zhòngyào chǎngjǐng.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Plan your illustration by thinking about the colours, illustration style and placement of characters.</div><div class=\"t3v2-lang t3v2-zh\">3. 思考颜色、插图风格和人物的位置，规划你的插图。</div><div class=\"t3v2-lang t3v2-py\">3. Sīkǎo yánsè, chātú fēnggé hé rénwù de wèizhì, guīhuà nǐ de chātú.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Draw and colour your illustration.</div><div class=\"t3v2-lang t3v2-zh\">4. 画出你的插图并上色。</div><div class=\"t3v2-lang t3v2-py\">4. Huà chū nǐ de chātú bìng shàngsè.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Present your illustration and explain how your artistic choices help readers understand the story.</div><div class=\"t3v2-lang t3v2-zh\">5. 展示你的插图，并解释你的艺术选择如何帮助读者理解故事。</div><div class=\"t3v2-lang t3v2-py\">5. Zhǎnshì nǐ de chātú, bìng jiěshì nǐ de yìshù xuǎnzé rúhé bāngzhù dúzhě lǐjiě gùshì.</div></div>\n\n\n\n\n\n\n\n<h3 class=\"t3v2-section\"><div class=\"t3v2-lang t3v2-en\">3.3 How Pictures Tell the Story</div><div class=\"t3v2-lang t3v2-zh\">3.3 图片如何讲故事</div><div class=\"t3v2-lang t3v2-py\">3.3 Túpiàn Rúhé Jiǎng Gùshì</div></h3>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Pictures as Storytellers</div><div class=\"t3v2-lang t3v2-zh\">作为叙述者的图像</div><div class=\"t3v2-lang t3v2-py\">Zuòwéi xùshù zhě de túxiàng</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Pictures can tell a story without many words.</div><div class=\"t3v2-lang t3v2-zh\">图片可以不用很多文字来讲故事。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Kěyǐ Bù Yòng Hěnduō Wénzì Lái Jiǎng Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Children often understand pictures first.</div><div class=\"t3v2-lang t3v2-zh\">孩子通常先理解图片。</div><div class=\"t3v2-lang t3v2-py\">Háizi Tōngcháng Xiān Lǐjiě Túpiàn.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Pictures show actions, feelings, and events.</div><div class=\"t3v2-lang t3v2-zh\">图片表现动作、情感和事件。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Biǎoxiàn Dòngzuò, Qínggǎn Hé Shìjiàn.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Good illustrations help readers imagine the story.</div><div class=\"t3v2-lang t3v2-zh\">好的插图帮助读者想象故事。</div><div class=\"t3v2-lang t3v2-py\">Hǎo de Chātú Bāngzhù Dúzhě Xiǎngxiàng Gùshì.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Pictures Give Information</div><div class=\"t3v2-lang t3v2-zh\">图片提供信息</div><div class=\"t3v2-lang t3v2-py\">Túpiàn tígōng xìnxī</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Pictures tell us:</div><div class=\"t3v2-lang t3v2-zh\">图片告诉我们：</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Gàosu Wǒmen:</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Who the characters are.</div><div class=\"t3v2-lang t3v2-zh\">谁是故事人物。</div><div class=\"t3v2-lang t3v2-py\">Shéi Shì Gùshì Rénwù.</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Where the story happens.</div><div class=\"t3v2-lang t3v2-zh\">故事在哪里发生。</div><div class=\"t3v2-lang t3v2-py\">Gùshì Zài Nǎlǐ Fāshēng.</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">What the characters are doing.</div><div class=\"t3v2-lang t3v2-zh\">人物正在做什么。</div><div class=\"t3v2-lang t3v2-py\">Rénwù Zhèngzài Zuò Shénme.</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">How the characters feel.</div><div class=\"t3v2-lang t3v2-zh\">人物有什么感受。</div><div class=\"t3v2-lang t3v2-py\">Rénwù Yǒu Shénme Gǎnshòu.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Pictures Show Feelings</div><div class=\"t3v2-lang t3v2-zh\">图片展现情感</div><div class=\"t3v2-lang t3v2-py\">Túpiàn zhǎnxiàn qínggǎn</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Facial expressions show emotions.</div><div class=\"t3v2-lang t3v2-zh\">面部表情表达情绪。</div><div class=\"t3v2-lang t3v2-py\">Miànbù Biǎoqíng Biǎodá Qíngxù.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Body language gives clues.</div><div class=\"t3v2-lang t3v2-zh\">肢体语言提供线索。</div><div class=\"t3v2-lang t3v2-py\">Zhītǐ Yǔyán Tígōng Xiànsuǒ.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Colours also show feelings.</div><div class=\"t3v2-lang t3v2-zh\">颜色也表达情绪。</div><div class=\"t3v2-lang t3v2-py\">Yánsè Yě Biǎodá Qíngxù.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Children learn to read emotions through pictures.</div><div class=\"t3v2-lang t3v2-zh\">孩子通过图片学习理解情绪。</div><div class=\"t3v2-lang t3v2-py\">Háizi Tōngguò Túpiàn Xuéxí Lǐjiě Qíngxù.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">What Is Counterpoint?</div><div class=\"t3v2-lang t3v2-zh\">什么是对位？</div><div class=\"t3v2-lang t3v2-py\">Shénme shì duì wèi?</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Counterpoint happens when pictures and words tell different things.</div><div class=\"t3v2-lang t3v2-zh\">对位是指图片和文字表达不同的信息。</div><div class=\"t3v2-lang t3v2-py\">Duìwèi Shì Zhǐ Túpiàn Hé Wénzì Biǎodá Bùtóng de Xìnxī.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The words tell one story.</div><div class=\"t3v2-lang t3v2-zh\">文字讲一个故事。</div><div class=\"t3v2-lang t3v2-py\">Wénzì Jiǎng Yí Gè Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The pictures tell another story.</div><div class=\"t3v2-lang t3v2-zh\">图片讲另一个故事。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Jiǎng Lìng Yí Gè Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Readers use both to understand the full meaning.</div><div class=\"t3v2-lang t3v2-zh\">读者结合两者来理解完整的意思。</div><div class=\"t3v2-lang t3v2-py\">Dúzhě Jiéhé Liǎngzhě Lái Lǐjiě Wánzhěng de Yìsi.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Example of Counterpoint</div><div class=\"t3v2-lang t3v2-zh\">对位示例</div><div class=\"t3v2-lang t3v2-py\">Duì wèi shìlì</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The text says,</div><div class=\"t3v2-lang t3v2-zh\">文字写着：</div><div class=\"t3v2-lang t3v2-py\">Wénzì Xiězhe:</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">\"I am not afraid.\"</div><div class=\"t3v2-lang t3v2-zh\">“我一点也不害怕。”</div><div class=\"t3v2-lang t3v2-py\">“Wǒ Yìdiǎn Yě Bù Hàipà.”</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">But the picture shows the child hiding.</div><div class=\"t3v2-lang t3v2-zh\">但是图片显示孩子躲起来。</div><div class=\"t3v2-lang t3v2-py\">Dànshì Túpiàn Xiǎnshì Háizi Duǒ Qǐlái.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Readers understand the child is actually afraid.</div><div class=\"t3v2-lang t3v2-zh\">读者知道孩子其实很害怕。</div><div class=\"t3v2-lang t3v2-py\">Dúzhě Zhīdào Háizi Qíshí Hěn Hàipà.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">What Is Irony?</div><div class=\"t3v2-lang t3v2-zh\">什么是反讽？</div><div class=\"t3v2-lang t3v2-py\">Shénme shì fǎnfěng?</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Irony happens when the apparent meaning of words differs from what the picture or situation shows.</div><div class=\"t3v2-lang t3v2-zh\">反讽是指文字表面上的意思与实际情况或图片呈现的意思不同。</div><div class=\"t3v2-lang t3v2-py\">Fǎnfěng Shì Zhǐ Wénzì Biǎomiàn Shàng de Yìsi Yǔ Shíjì Qíngkuàng Huò Túpiàn Chéngxiàn de Yìsi Bùtóng.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Pictures and words may create humour.</div><div class=\"t3v2-lang t3v2-zh\">图片和文字可以创造幽默。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Hé Wénzì Kěyǐ Chuàngzào Yōumò.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Readers notice the difference.</div><div class=\"t3v2-lang t3v2-zh\">读者注意到两者的不同。</div><div class=\"t3v2-lang t3v2-py\">Dúzhě Zhùyì Dào Liǎngzhě de Bùtóng.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">This makes the story more interesting.</div><div class=\"t3v2-lang t3v2-zh\">这让故事更加有趣。</div><div class=\"t3v2-lang t3v2-py\">Zhè Ràng Gùshì Gèngjiā Yǒuqù.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Example of Irony</div><div class=\"t3v2-lang t3v2-zh\">反讽示例</div><div class=\"t3v2-lang t3v2-py\">Fǎnfěng shìlì</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The text says,</div><div class=\"t3v2-lang t3v2-zh\">文字写着：</div><div class=\"t3v2-lang t3v2-py\">Wénzì Xiězhe:</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">\"The room is very clean.\"</div><div class=\"t3v2-lang t3v2-zh\">“房间非常干净。”</div><div class=\"t3v2-lang t3v2-py\">“Fángjiān Fēicháng Gānjìng.”</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">But the picture shows toys everywhere.</div><div class=\"t3v2-lang t3v2-zh\">但是图片显示玩具到处都是。</div><div class=\"t3v2-lang t3v2-py\">Dànshì Túpiàn Xiǎnshì Wánjù Dàochù Dōu Shì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Readers understand the joke.</div><div class=\"t3v2-lang t3v2-zh\">读者明白这个笑话。</div><div class=\"t3v2-lang t3v2-py\">Dúzhě Míngbái Zhège Xiàohuà.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Visual Clues</div><div class=\"t3v2-lang t3v2-zh\">视觉线索</div><div class=\"t3v2-lang t3v2-py\">Shìjué xiànsuǒ</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Visual clues help readers understand the story.</div><div class=\"t3v2-lang t3v2-zh\">视觉线索帮助读者理解故事。</div><div class=\"t3v2-lang t3v2-py\">Shìjué Xiànsuǒ Bāngzhù Dúzhě Lǐjiě Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Look carefully at:</div><div class=\"t3v2-lang t3v2-zh\">仔细观察：</div><div class=\"t3v2-lang t3v2-py\">Zǐxì Guānchá:</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Faces</div><div class=\"t3v2-lang t3v2-zh\">表情</div><div class=\"t3v2-lang t3v2-py\">Biǎoqíng</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Eyes</div><div class=\"t3v2-lang t3v2-zh\">眼睛</div><div class=\"t3v2-lang t3v2-py\">Yǎnjing</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Body movements</div><div class=\"t3v2-lang t3v2-zh\">动作</div><div class=\"t3v2-lang t3v2-py\">Dòngzuò</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Background</div><div class=\"t3v2-lang t3v2-zh\">背景</div><div class=\"t3v2-lang t3v2-py\">Bèijǐng</div></div>\n<div class=\"t3v2-bullet\"><div class=\"t3v2-lang t3v2-en\">Colours</div><div class=\"t3v2-lang t3v2-zh\">颜色</div><div class=\"t3v2-lang t3v2-py\">Yánsè</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Wordless Storytelling</div></h4>\n<figure class=\"t3v2-figure\"><img alt=\"Topic 3 teaching illustration\" loading=\"lazy\" src=\"./assets/topic3_little_seed_four_panels.png\"/></figure>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Some picture books have no words.</div><div class=\"t3v2-lang t3v2-zh\">有些图画书没有文字。</div><div class=\"t3v2-lang t3v2-py\">Yǒuxiē Túhuàshū Méiyǒu Wénzì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">The pictures tell the whole story.</div><div class=\"t3v2-lang t3v2-zh\">图片讲述整个故事。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Jiǎngshù Zhěnggè Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Readers create their own dialogue.</div><div class=\"t3v2-lang t3v2-zh\">读者可以自己创造对话。</div><div class=\"t3v2-lang t3v2-py\">Dúzhě Kěyǐ Zìjǐ Chuàngzào Duìhuà.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Each reader may imagine a different story.</div><div class=\"t3v2-lang t3v2-zh\">每位读者都可能想象不同的故事。</div><div class=\"t3v2-lang t3v2-py\">Měiwèi Dúzhě Dōu Kěnéng Xiǎngxiàng Bùtóng de Gùshì.</div></div>\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">Benefits of Wordless Picture Books</div><div class=\"t3v2-lang t3v2-zh\">无字绘本的益处</div><div class=\"t3v2-lang t3v2-py\">Wúzì Huìběn de Yìchù</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Wordless books develop imagination.</div><div class=\"t3v2-lang t3v2-zh\">无字图画书培养想象力。</div><div class=\"t3v2-lang t3v2-py\">Wúzì Túhuàshū Péiyǎng Xiǎngxiànglì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">They encourage speaking.</div><div class=\"t3v2-lang t3v2-zh\">它们鼓励孩子说话。</div><div class=\"t3v2-lang t3v2-py\">Tāmen Gǔlì Háizi Shuōhuà.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">They improve observation skills.</div><div class=\"t3v2-lang t3v2-zh\">它们提高观察能力。</div><div class=\"t3v2-lang t3v2-py\">Tāmen Tígāo Guānchá Nénglì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Every child can tell a different story.</div><div class=\"t3v2-lang t3v2-zh\">每个孩子都可以讲不同的故事。</div><div class=\"t3v2-lang t3v2-py\">Měi Gè Háizi Dōu Kěyǐ Jiǎng Bùtóng de Gùshì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Pictures are powerful storytellers.</div><div class=\"t3v2-lang t3v2-zh\">图片是很有力量的故事讲述者。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Shì Hěn Yǒu Lìliàng de Gùshì Jiǎngshùzhě.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Pictures add meaning to words.</div><div class=\"t3v2-lang t3v2-zh\">图片丰富文字的意义。</div><div class=\"t3v2-lang t3v2-py\">Túpiàn Fēngfù Wénzì de Yìyì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Readers should notice visual clues.</div><div class=\"t3v2-lang t3v2-zh\">读者应该注意视觉线索。</div><div class=\"t3v2-lang t3v2-py\">Dúzhě Yīnggāi Zhùyì Shìjué Xiànsuǒ.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Teachers should encourage children to read pictures carefully.</div><div class=\"t3v2-lang t3v2-zh\">教师应该鼓励孩子仔细阅读图片。</div><div class=\"t3v2-lang t3v2-py\">Jiàoshī Yīnggāi Gǔlì Háizi Zǐxì Yuèdú Túpiàn.</div></div>\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 1: Tell the Story from Pictures</div><div class=\"t3v2-lang t3v2-zh\">活动一：看图讲故事</div><div class=\"t3v2-lang t3v2-py\">Huódòng Yī: Kàn Tú Jiǎng Gùshì</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Interpret illustrations and tell a story using visual information.</div><div class=\"t3v2-lang t3v2-zh\">理解插图，并根据视觉信息讲述故事。</div><div class=\"t3v2-lang t3v2-py\">Lǐjiě chātú, bìng gēnjù shìjué xìnxī jiǎngshù gùshì.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">A picture book with a clear sequence of illustrations.</div><div class=\"t3v2-lang t3v2-zh\">一本具有清晰连续插图的图画书。</div><div class=\"t3v2-lang t3v2-py\">Yì běn jùyǒu qīngxī liánxù chātú de túhuàshū.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Work in pairs.</div><div class=\"t3v2-lang t3v2-zh\">1. 两人一组。</div><div class=\"t3v2-lang t3v2-py\">1. Liǎng rén yì zǔ.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Look through the picture book without reading the words.</div><div class=\"t3v2-lang t3v2-zh\">2. 翻看图画书，但不要阅读文字。</div><div class=\"t3v2-lang t3v2-py\">2. Fānkàn túhuàshū, dàn búyào yuèdú wénzì.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Observe the characters, actions and settings in the illustrations.</div><div class=\"t3v2-lang t3v2-zh\">3. 观察插图中的人物、动作和故事背景。</div><div class=\"t3v2-lang t3v2-py\">3. Guānchá chātú zhōng de rénwù, dòngzuò hé gùshì bèijǐng.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Tell the story in your own words using only the pictures.</div><div class=\"t3v2-lang t3v2-zh\">4. 只根据图片，用自己的话讲述故事。</div><div class=\"t3v2-lang t3v2-py\">4. Zhǐ gēnjù túpiàn, yòng zìjǐ de huà jiǎngshù gùshì.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Read the original text and compare it with your story.</div><div class=\"t3v2-lang t3v2-zh\">5. 阅读原文，并与你讲述的故事进行比较。</div><div class=\"t3v2-lang t3v2-py\">5. Yuèdú yuánwén, bìng yǔ nǐ jiǎngshù de gùshì jìnxíng bǐjiào.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">6. Discuss what information the pictures provided that helped you understand the story.</div><div class=\"t3v2-lang t3v2-zh\">6. 讨论图片提供了哪些信息来帮助你理解故事。</div><div class=\"t3v2-lang t3v2-py\">6. Tǎolùn túpiàn tígōng le nǎxiē xìnxī lái bāngzhù nǐ lǐjiě gùshì.</div></div>\n\n\n\n\n\n\n\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 2: Find the Visual Clues</div><div class=\"t3v2-lang t3v2-zh\">活动二：寻找视觉线索</div><div class=\"t3v2-lang t3v2-py\">Huódòng Èr: Xúnzhǎo Shìjué Xiànsuǒ</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Identify visual clues and explain how they communicate meaning in a story.</div><div class=\"t3v2-lang t3v2-zh\">辨认视觉线索，并解释这些线索如何传达故事的意义。</div><div class=\"t3v2-lang t3v2-py\">Biànrèn shìjué xiànsuǒ, bìng jiěshì zhèxiē xiànsuǒ rúhé chuándá gùshì de yìyì.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">One detailed picture-book illustration and a worksheet.</div><div class=\"t3v2-lang t3v2-zh\">一幅内容丰富的图画书插图和一张记录表。</div><div class=\"t3v2-lang t3v2-py\">Yì fú nèiróng fēngfù de túhuàshū chātú hé yì zhāng jìlù biǎo.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Work in small groups.</div><div class=\"t3v2-lang t3v2-zh\">1. 小组合作。</div><div class=\"t3v2-lang t3v2-py\">1. Xiǎozǔ hézuò.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Study the illustration carefully.</div><div class=\"t3v2-lang t3v2-zh\">2. 仔细观察插图。</div><div class=\"t3v2-lang t3v2-py\">2. Zǐxì guānchá chātú.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Find five visual clues, such as facial expressions, gestures, colours or objects.</div><div class=\"t3v2-lang t3v2-zh\">3. 找出五个视觉线索，例如面部表情、手势、颜色或物品。</div><div class=\"t3v2-lang t3v2-py\">3. Zhǎochū wǔ gè shìjué xiànsuǒ, lìrú miànbù biǎoqíng, shǒushì, yánsè huò wùpǐn.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Record each clue and explain what it might tell you about the story.</div><div class=\"t3v2-lang t3v2-zh\">4. 记录每个线索，并解释它可能告诉你哪些故事信息。</div><div class=\"t3v2-lang t3v2-py\">4. Jìlù měi gè xiànsuǒ, bìng jiěshì tā kěnéng gàosu nǐ nǎxiē gùshì xìnxī.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Present your findings and explain which visual clues support your interpretations.</div><div class=\"t3v2-lang t3v2-zh\">5. 展示你们的发现，并解释哪些视觉线索支持你们的理解。</div><div class=\"t3v2-lang t3v2-py\">5. Zhǎnshì nǐmen de fāxiàn, bìng jiěshì nǎxiē shìjué xiànsuǒ zhīchí nǐmen de lǐjiě.</div></div>\n\n\n\n\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 3: Create a Wordless Story</div><div class=\"t3v2-lang t3v2-zh\">活动三：创作无字故事</div><div class=\"t3v2-lang t3v2-py\">Huódòng Sān: Chuàngzuò Wúzì Gùshì</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Create a simple story using pictures without written words.</div><div class=\"t3v2-lang t3v2-zh\">只用图片、不使用文字来创作一个简单的故事。</div><div class=\"t3v2-lang t3v2-py\">Zhǐ yòng túpiàn, bù shǐyòng wénzì lái chuàngzuò yí gè jiǎndān de gùshì.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Four sheets of drawing paper, pencils and colouring materials.</div><div class=\"t3v2-lang t3v2-zh\">四张画纸、铅笔和彩色绘画工具。</div><div class=\"t3v2-lang t3v2-py\">Sì zhāng huàzhǐ, qiānbǐ hé cǎisè huìhuà gōngjù.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Work in small groups.</div><div class=\"t3v2-lang t3v2-zh\">1. 小组合作。</div><div class=\"t3v2-lang t3v2-py\">1. Xiǎozǔ hézuò.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Think of a simple story with a beginning, middle and ending.</div><div class=\"t3v2-lang t3v2-zh\">2. 构思一个有开头、经过和结尾的简单故事。</div><div class=\"t3v2-lang t3v2-py\">2. Gòusī yí gè yǒu kāitóu, jīngguò hé jiéwěi de jiǎndān gùshì.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Draw four pictures that show the story in sequence.</div><div class=\"t3v2-lang t3v2-zh\">3. 画四幅图片，按照顺序表现故事。</div><div class=\"t3v2-lang t3v2-py\">3. Huà sì fú túpiàn, ànzhào shùnxù biǎoxiàn gùshì.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Do not include any written words in your pictures.</div><div class=\"t3v2-lang t3v2-zh\">4. 不要在图片中加入任何文字。</div><div class=\"t3v2-lang t3v2-py\">4. Búyào zài túpiàn zhōng jiārù rènhé wénzì.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Exchange your pictures with another group and ask them to tell your story.</div><div class=\"t3v2-lang t3v2-zh\">5. 与另一组交换图片，并请他们讲述你的故事。</div><div class=\"t3v2-lang t3v2-py\">5. Yǔ lìng yì zǔ jiāohuàn túpiàn, bìng qǐng tāmen jiǎngshù nǐ de gùshì.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">6. Compare their interpretation with the story you intended to tell.</div><div class=\"t3v2-lang t3v2-zh\">6. 比较他们的理解与你原本想表达的故事。</div><div class=\"t3v2-lang t3v2-py\">6. Bǐjiào tāmen de lǐjiě yǔ nǐ yuánběn xiǎng biǎodá de gùshì.</div></div>\n\n\n\n\n\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 4: Counterpoint and Irony Hunt</div><div class=\"t3v2-lang t3v2-zh\">活动四：寻找对位与反讽</div><div class=\"t3v2-lang t3v2-py\">Huódòng Sì: Xúnzhǎo Duìwèi Yǔ Fǎnfěng</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Identify examples of counterpoint and irony between words and pictures.</div><div class=\"t3v2-lang t3v2-zh\">辨认文字与图片之间的对位和反讽例子。</div><div class=\"t3v2-lang t3v2-py\">Biànrèn wénzì yǔ túpiàn zhījiān de duìwèi hé fǎnfěng lìzi.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Picture books or teacher-selected pages showing differences between words and illustrations.</div><div class=\"t3v2-lang t3v2-zh\">图画书或教师选择的文字与插图表达不同信息的页面。</div><div class=\"t3v2-lang t3v2-py\">Túhuàshū huò jiàoshī xuǎnzé de wénzì yǔ chātú biǎodá bùtóng xìnxī de yèmiàn.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Work in small groups.</div><div class=\"t3v2-lang t3v2-zh\">1. 小组合作。</div><div class=\"t3v2-lang t3v2-py\">1. Xiǎozǔ hézuò.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Choose a picture book or examine the pages provided by your lecturer.</div><div class=\"t3v2-lang t3v2-zh\">2. 选择一本图画书，或观察讲师提供的页面。</div><div class=\"t3v2-lang t3v2-py\">2. Xuǎnzé yì běn túhuàshū, huò guānchá jiǎngshī tígōng de yèmiàn.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. Find an example where the pictures add different information to the words. This may be counterpoint.</div><div class=\"t3v2-lang t3v2-zh\">3. 找出图片提供与文字不同信息的例子。这可能是对位。</div><div class=\"t3v2-lang t3v2-py\">3. Zhǎochū túpiàn tígōng yǔ wénzì bùtóng xìnxī de lìzi. Zhè kěnéng shì duìwèi.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Look for an example where the words and pictures create a humorous or surprising contrast. This may be irony.</div><div class=\"t3v2-lang t3v2-zh\">4. 寻找文字与图片形成幽默或意外对比的例子。这可能是反讽。</div><div class=\"t3v2-lang t3v2-py\">4. Xúnzhǎo wénzì yǔ túpiàn xíngchéng yōumò huò yìwài duìbǐ de lìzi. Zhè kěnéng shì fǎnfěng.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Explain what the words say, what the pictures show and how the two work together.</div><div class=\"t3v2-lang t3v2-zh\">5. 解释文字说了什么、图片显示了什么，以及两者如何共同讲述故事。</div><div class=\"t3v2-lang t3v2-py\">5. Jiěshì wénzì shuō le shénme, túpiàn xiǎnshì le shénme, yǐjí liǎng zhě rúhé gòngtóng jiǎngshù gùshì.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">6. Share your findings with the class. If you cannot find both examples, explain what you found and why.</div><div class=\"t3v2-lang t3v2-zh\">6. 向全班分享你们的发现。如果找不到两种例子，请说明你们发现了什么以及原因。</div><div class=\"t3v2-lang t3v2-py\">6. Xiàng quánbān fēnxiǎng nǐmen de fāxiàn. Rúguǒ zhǎo bú dào liǎng zhǒng lìzi, qǐng shuōmíng nǐmen fāxiàn le shénme yǐjí yuányīn.</div></div>\n\n\n\n\n\n<h4 class=\"t3v2-heading t3v3-activity-title\"><div class=\"t3v2-lang t3v2-en\">Hands-on Activity 5: Picture Detective Challenge</div><div class=\"t3v2-lang t3v2-zh\">活动五：图片侦探挑战</div><div class=\"t3v2-lang t3v2-py\">Huódòng Wǔ: Túpiàn Zhēntàn Tiǎozhàn</div></h4><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Objective</div><div class=\"t3v2-lang t3v2-zh\">目的</div><div class=\"t3v2-lang t3v2-py\">Mùdì</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Interpret characters, actions, emotions and possible events using visual clues.</div><div class=\"t3v2-lang t3v2-zh\">根据视觉线索理解人物、动作、情绪和可能发生的事件。</div><div class=\"t3v2-lang t3v2-py\">Gēnjù shìjué xiànsuǒ lǐjiě rénwù, dòngzuò, qíngxù hé kěnéng fāshēng de shìjiàn.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Materials</div><div class=\"t3v2-lang t3v2-zh\">材料</div><div class=\"t3v2-lang t3v2-py\">Cáiliào</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">One detailed picture-book illustration selected by the lecturer.</div><div class=\"t3v2-lang t3v2-zh\">一幅由讲师选择、内容丰富的图画书插图。</div><div class=\"t3v2-lang t3v2-py\">Yì fú yóu jiǎngshī xuǎnzé, nèiróng fēngfù de túhuàshū chātú.</div></div><div class=\"t3v2-label t3v3-activity-label\"><div class=\"t3v2-lang t3v2-en\">Instructions</div><div class=\"t3v2-lang t3v2-zh\">说明</div><div class=\"t3v2-lang t3v2-py\">Shuōmíng</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">1. Look carefully at the illustration shown by your lecturer.</div><div class=\"t3v2-lang t3v2-zh\">1. 仔细观察讲师展示的插图。</div><div class=\"t3v2-lang t3v2-py\">1. Zǐxì guānchá jiǎngshī zhǎnshì de chātú.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">2. Answer: Who are the characters? What is happening? How do the characters feel? What might happen next?</div><div class=\"t3v2-lang t3v2-zh\">2. 回答：故事人物是谁？正在发生什么事情？故事人物有什么感受？接下来可能发生什么？</div><div class=\"t3v2-lang t3v2-py\">2. Huídá: Gùshì rénwù shì shéi? Zhèngzài fāshēng shénme shìqíng? Gùshì rénwù yǒu shénme gǎnshòu? Jiēxiàlái kěnéng fāshēng shénme?</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">3. For each answer, identify at least one visual clue that supports your idea.</div><div class=\"t3v2-lang t3v2-zh\">3. 为每个答案找出至少一个视觉线索来支持你的想法。</div><div class=\"t3v2-lang t3v2-py\">3. Wèi měi gè dá’àn zhǎochū zhìshǎo yí gè shìjué xiànsuǒ lái zhīchí nǐ de xiǎngfǎ.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">4. Compare your answers with a partner.</div><div class=\"t3v2-lang t3v2-zh\">4. 与同伴比较你的答案。</div><div class=\"t3v2-lang t3v2-py\">4. Yǔ tóngbàn bǐjiào nǐ de dá’àn.</div></div><div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">5. Discuss different interpretations with the class and explain which clues support each interpretation.</div><div class=\"t3v2-lang t3v2-zh\">5. 与全班讨论不同的理解，并解释哪些线索支持每一种理解。</div><div class=\"t3v2-lang t3v2-py\">5. Yǔ quánbān tǎolùn bùtóng de lǐjiě, bìng jiěshì nǎxiē xiànsuǒ zhīchí měi yì zhǒng lǐjiě.</div></div>\n\n\n\n\n\n\n\n<h4 class=\"t3v2-heading\"><div class=\"t3v2-lang t3v2-en\">End of Topic 3</div><div class=\"t3v2-lang t3v2-zh\">主题 3 结束</div><div class=\"t3v2-lang t3v2-py\">Zhǔtí 3 jiéshù</div></h4>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">After completing Topic 3, students should be able to:</div><div class=\"t3v2-lang t3v2-zh\">完成第三主题后，学生应该能够：</div><div class=\"t3v2-lang t3v2-py\">Wánchéng Dì Sān Zhǔtí Hòu, Xuéshēng Yīnggāi Nénggòu:</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Identify the anatomy of a picture book.</div><div class=\"t3v2-lang t3v2-zh\">辨认图画书的结构。</div><div class=\"t3v2-lang t3v2-py\">Biànrèn Túhuàshū de Jiégòu.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Evaluate illustrations using media, style, line, colour and composition.</div><div class=\"t3v2-lang t3v2-zh\">运用媒材、风格、线条、颜色和构图评估插图。</div><div class=\"t3v2-lang t3v2-py\">Yùnyòng Méicái, Fēnggé, Xiàntiáo, Yánsè Hé Gòutú Pínggū Chātú.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Explain how pictures communicate meaning through visual clues, counterpoint and irony.</div><div class=\"t3v2-lang t3v2-zh\">解释图片如何通过视觉线索、对位和反讽传达意义。</div><div class=\"t3v2-lang t3v2-py\">Jiěshì Túpiàn Rúhé Tōngguò Shìjué Xiànsuǒ, Duìwèi Hé Fǎnfěng Chuándá Yìyì.</div></div>\n<div class=\"t3v2-body\"><div class=\"t3v2-lang t3v2-en\">Select and use picture books more effectively in early childhood classrooms.</div><div class=\"t3v2-lang t3v2-zh\">更有效地在幼儿课堂中选择和运用图画书。</div><div class=\"t3v2-lang t3v2-py\">Gèng Yǒuxiào de Zài Yòu'ér Kètáng Zhōng Xuǎnzé Hé Yùnyòng Túhuàshū.</div></div>\n";
const originalOpenTopic3=window.openTopic3;
window.openTopic3=function(){
  originalOpenTopic3();
  const root=document.getElementById('lessonContent');
  const quiz=root.querySelector('.topic3Quiz');
  if(!quiz) { console.error('Topic 3 quiz not found; original lesson preserved'); return; }
  const quizAndFollowing=[]; let node=quiz; while(node){const next=node.nextSibling;quizAndFollowing.push(node);node=next;}
  root.innerHTML='<section class="topic3CompleteLecture"><div class="topic3PreviewNotice">Complete Topic 3 layout preview / 第三主题完整预览 / Dì sān zhǔtí wánzhěng yùlǎn</div>'+topic3CompleteLectureHTML+'</section>';
  quizAndFollowing.forEach(n=>root.appendChild(n));
};
})();
